def solve(a, b):
    """Return Levenshtein edit distance between strings a and b.
    Implements DP with O(min(m,n)) space to handle long inputs.
    Treats None as empty string.
    """
    if a is None:
        a = ''
    if b is None:
        b = ''
    m, n = len(a), len(b)
    # Ensure that n is the smaller dimension to use less space
    if n > m:
        a, b = b, a
        m, n = n, m
    # prev row
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
        prev = cur
    return prev[n]

