    visited = [[False]*cols for _ in range(rows)]
    visited[0][0] = True
    directions = [(1,0), (-1,0), (0,1), (0,-1)]
    while q:
        r, c, d = q.popleft()
        if r == rows-1 and c == cols-1:
            return d
        for dr, dc in directions:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nur][nc] == 0:
