def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited coins of given denominations.
    If it is impossible, return -1.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] is min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive coins just in case
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

