def solve(grid):
    """Count islands in a binary grid that may be jagged.
    An island is a group of adjacent cells with value 1 (4-directional).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    count = 0
    for i in range(rows):
        for j, val in enumerate(grid[i]):
            if val == 1 and (i, j) not in visited:
                count += 1
                stack = [(i, j)]
                visited.add((i, j))
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] == 1 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
    return count

